#!/usr/bin/env bash
set -euo pipefail

# Assembles charts/ai-foundry/.local/secrets.yaml from the key material
# in the repo-root .local/ (generated by hacks/setup_keys.sh and
# hacks/langfuse.sh) plus Postgres settings from environment variables.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT_LOCAL="$(cd "$SCRIPT_DIR/../.." && pwd)/.local"
OUT="$SCRIPT_DIR/.local/secrets.yaml"

PG_HOST="postgres-postgresql.postgres.svc.cluster.local:5432"

for f in client-private.pem provisioner-private.pem redis-token-enc.key cookie-secret.key \
         litellm-master-key mcp-consent-key \
         langfuse-public-key langfuse-secret-key; do
    if [[ ! -f "$ROOT_LOCAL/$f" ]]; then
        echo "❌ Missing $ROOT_LOCAL/$f — run hacks/setup_keys.sh and hacks/langfuse.sh first" >&2
        exit 1
    fi
done

mkdir -p "$(dirname "$OUT")"

# ai-foundry-be and adk-be-app read Langfuse's public API with
# `Basic base64(publicKey:secretKey)` of the project hacks/langfuse.sh creates.
LANGFUSE_AUTH_HEADER="Basic $(printf '%s:%s' \
    "$(tr -d '\n' < "$ROOT_LOCAL/langfuse-public-key")" \
    "$(tr -d '\n' < "$ROOT_LOCAL/langfuse-secret-key")" | base64 | tr -d '\n')"

# adk-be-app and ai-foundry-workflows (Python) need the asyncpg driver;
# ai-foundry-be (Rust) needs a plain postgresql:// URL to the *same* database.
jq -n \
    --rawfile privateKey            "$ROOT_LOCAL/client-private.pem" \
    --rawfile provisionerPrivateKey "$ROOT_LOCAL/provisioner-private.pem" \
    --rawfile tokenEncKey           "$ROOT_LOCAL/redis-token-enc.key" \
    --rawfile cookieSecret          "$ROOT_LOCAL/cookie-secret.key" \
    --rawfile litellmMasterKey      "$ROOT_LOCAL/litellm-master-key" \
    --rawfile mcpConsentKey         "$ROOT_LOCAL/mcp-consent-key" \
    --arg pgConnAdk       "${ADK_PG_CONN:-postgresql+asyncpg://adk_user:postgres@${PG_HOST}/adk}" \
    --arg pgConnBe        "${AI_FOUNDRY_BE_PG_CONN:-postgresql://adk_user:postgres@${PG_HOST}/adk}" \
    --arg pgConnWorkspace "${WORKSPACE_PG_CONN:-postgresql://workspace_user:postgres@${PG_HOST}/workspace}" \
    --arg langfuseAuthHeader "$LANGFUSE_AUTH_HEADER" \
    '{
        "ai-foundry": {
            secrets: {
                accessControlKeys: {
                    privateKey: $privateKey
                },
                authtoolBffKeys: {
                    tokenEncKey:  ($tokenEncKey  | rtrimstr("\n")),
                    cookieSecret: ($cookieSecret | rtrimstr("\n")),
                    website:            { privateKey: $privateKey },
                    exchangeAuthz:      { privateKey: $privateKey },
                    exchangeCatalog:    { privateKey: $privateKey },
                    exchangeAiServices: { privateKey: $privateKey }
                },
                adkBeAppKeys: {
                    postgresConnectionString: $pgConnAdk,
                    langfuseAuthHeader: $langfuseAuthHeader
                },
                aiFoundryBeKeys: {
                    postgresConnectionString: $pgConnBe,
                    langfuseAuthHeader: $langfuseAuthHeader,
                    litellmAdminKey:     ($litellmMasterKey | rtrimstr("\n")),
                    mcpConsentKeySecret: ($mcpConsentKey    | rtrimstr("\n"))
                },
                aiFoundryWorkflowsKeys: {
                    postgresConnectionString: $pgConnAdk
                },
                aiFoundryProvisionerKeys: {
                    privateKey: $provisionerPrivateKey
                },
                workspaceServiceKeys: {
                    postgresConnectionString: $pgConnWorkspace
                }
            }
        }
    }' | yq -P > "$OUT"

echo "✅ Wrote AI Foundry secrets into $OUT"
